'use strict';

// MODULES //

var sin = require( '@stdlib/math/base/special/sin' );
var cos = require( '@stdlib/math/base/special/cos' );
var TWO_PI = require( '@stdlib/constants/float64/two-pi' );
var decompose = require( './decompose.js' );


// VARIABLES //

var NTRYH = [ 4, 2, 3, 5 ]; // Initial trial factors for FFT factorization


// MAIN //

/**
* Initializes the working arrays for the FFT algorithm.
*
* @private
* @param {number} n - length of the sequence
* @param {Float64Array} wa - array of twiddle factors
* @param {Int32Array} ifac - array containing factorization information
* @returns {void}
*/
function rffti1( n, wa, ifac ) {
	var argld;
	var argh;
	var nfm1;
	var ipm;
	var ido;
	var arg;
	var nf;
	var ip;
	var is;
	var ii;
	var ld;
	var fi;
	var l2;
	var l1;
	var k1;
	var j;
	var i;

	nf = decompose( n, ifac, NTRYH );
	argh = TWO_PI / n;
	is = 0;
	nfm1 = nf - 1;
	l1 = 1;
	if ( nfm1 === 0 ) {
		return;
	}
	for ( k1 = 1; k1 <= nfm1; k1++ ) {
		ip = ifac[ k1 + 2 - 1 ];
		ld = 0;
		l2 = ip * l1;
		ido = n / l2;
		ipm = ip - 1;
		for ( j = 1; j <= ipm; j++ ) {
			ld += l1;
			i = is;
			argld = ld * argh;
			fi = 0.0;
			for ( ii = 3; ii <= ido; ii += 2 ) {
				i += 2;
				fi += 1.0;
				arg = fi * argld;
				wa[ i - 1 - 1 ] = cos( arg );
				wa[ i - 1 ] = sin( arg );
			}
			is += ido;
		}
		l1 = l2;
	}
}


// EXPORTS //

module.exports = rffti1;
